    var distributerOrderListGridStore = function (ind) {
        var _store = new Ext.data.GroupingStore({
            proxy: new Ext.data.HttpProxy({
                url: modURL + "&op=listScheduleOrder",
                method: "post"
            }),
            reader: new Ext.data.JsonReader(
                    {
                        totalProperty: "totalCount",
                        idProperty: "order_id",
                        root: "data"
                    },
            [
                "order_id",
                "order_no",
                "bcor_createdon",
                "cpd_id",
                "branch_id",
                "order_status",
                "order_no_last_id",
                "cpd_Name",
                "branch_name"
            ]
                    ),
            sortInfo: {
                field: "order_id",
                direction: "DESC"
            },
            groupField: "",
            groupDir: "ASC",
            remoteSort: true,
            autoLoad: false,
            root: "data",
            listeners: {
                load: function () {
                    Ext.getCmp("outward_schedule_gridDOL" + ind).getView().refresh();
                    Ext.getCmp("outward_schedule_gridDOL" + ind).getSelectionModel().selectRow(0);
                }
            }
        });
        _store.load({
            params: {
                start: 0,
                limit: recs_per_page
            }
        });

        return _store;
    };
